CREATE OR REPLACE FUNCTION private.current_user_is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'admin'::public.app_role) $$;
REVOKE ALL ON FUNCTION private.current_user_is_admin() FROM PUBLIC, anon;
GRANT USAGE ON SCHEMA private TO authenticated;
GRANT EXECUTE ON FUNCTION private.current_user_is_admin() TO authenticated;
DROP POLICY IF EXISTS "Admins can manage roles" ON public.user_roles;
CREATE POLICY "Admins can manage roles" ON public.user_roles FOR ALL TO authenticated USING (private.current_user_is_admin()) WITH CHECK (private.current_user_is_admin());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.student_groups, public.group_members, public.khadim_registrations, public.khadim_schedule TO authenticated;
GRANT ALL ON public.student_groups, public.group_members, public.khadim_registrations, public.khadim_schedule TO service_role;
DROP POLICY IF EXISTS "Admins manage groups" ON public.student_groups;
CREATE POLICY "Admins manage groups" ON public.student_groups FOR ALL TO authenticated USING (private.current_user_is_admin()) WITH CHECK (private.current_user_is_admin());
DROP POLICY IF EXISTS "Admins manage members" ON public.group_members;
CREATE POLICY "Admins manage members" ON public.group_members FOR ALL TO authenticated USING (private.current_user_is_admin()) WITH CHECK (private.current_user_is_admin());
DROP POLICY IF EXISTS "Admins manage khadims" ON public.khadim_registrations;
CREATE POLICY "Admins manage khadims" ON public.khadim_registrations FOR ALL TO authenticated USING (private.current_user_is_admin()) WITH CHECK (private.current_user_is_admin());
DROP POLICY IF EXISTS "Admins manage schedule" ON public.khadim_schedule;
CREATE POLICY "Admins manage schedule" ON public.khadim_schedule FOR ALL TO authenticated USING (private.current_user_is_admin()) WITH CHECK (private.current_user_is_admin());
DROP POLICY IF EXISTS "Users can read own khadim reg" ON public.khadim_registrations;
CREATE POLICY "Users can read own khadim reg" ON public.khadim_registrations FOR SELECT TO authenticated USING (user_id = auth.uid() AND university_id = (SELECT university_id FROM public.profiles WHERE id = auth.uid()));
DROP POLICY IF EXISTS "Users see own schedule" ON public.khadim_schedule;
CREATE POLICY "Users see own schedule" ON public.khadim_schedule FOR SELECT TO authenticated USING (university_id = (SELECT university_id FROM public.profiles WHERE id = auth.uid()) AND EXISTS (SELECT 1 FROM public.khadim_registrations r WHERE r.id = khadim_id AND r.user_id = auth.uid() AND r.university_id = khadim_schedule.university_id));
CREATE OR REPLACE FUNCTION public.admin_student_directory() RETURNS TABLE(id uuid, full_name text, gender text, university_id uuid, batch_year text, department text, is_verified boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT private.current_user_is_admin() THEN RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501'; END IF; RETURN QUERY SELECT p.id,p.full_name,p.gender,p.university_id,p.batch_year,p.department,p.is_verified FROM public.profiles p ORDER BY p.full_name; END; $$;
REVOKE ALL ON FUNCTION public.admin_student_directory() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_student_directory() TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.validate_group_membership() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE g public.student_groups%ROWTYPE; p public.profiles%ROWTYPE; BEGIN SELECT * INTO g FROM public.student_groups WHERE id=NEW.group_id FOR UPDATE; SELECT * INTO p FROM public.profiles WHERE id=NEW.user_id; IF g.id IS NULL OR p.id IS NULL THEN RAISE EXCEPTION 'Choose an existing group and registered student'; END IF; IF g.university_id <> p.university_id OR lower(g.gender) <> lower(p.gender) THEN RAISE EXCEPTION 'Members must belong to the group university and gender'; END IF; IF NEW.role NOT IN ('Member','Amir','Naqeeb','Murshid') THEN RAISE EXCEPTION 'Choose a valid group role'; END IF; IF (SELECT count(*) FROM public.group_members WHERE group_id=NEW.group_id AND id IS DISTINCT FROM NEW.id)>=14 THEN RAISE EXCEPTION 'A group can have at most 14 students'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.validate_group_membership() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS validate_group_membership ON public.group_members;
CREATE TRIGGER validate_group_membership BEFORE INSERT OR UPDATE ON public.group_members FOR EACH ROW EXECUTE FUNCTION public.validate_group_membership();
CREATE OR REPLACE FUNCTION public.validate_group_details() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF length(trim(NEW.name))=0 OR lower(NEW.gender) NOT IN ('male','female') THEN RAISE EXCEPTION 'Group name and gender are required'; END IF; IF EXISTS (SELECT 1 FROM public.group_members m JOIN public.profiles p ON p.id=m.user_id WHERE m.group_id=NEW.id AND (p.university_id<>NEW.university_id OR lower(p.gender)<>lower(NEW.gender))) THEN RAISE EXCEPTION 'Remove incompatible members before changing the university or gender'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.validate_group_details() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER validate_group_details BEFORE INSERT OR UPDATE ON public.student_groups FOR EACH ROW EXECUTE FUNCTION public.validate_group_details();
CREATE OR REPLACE FUNCTION public.validate_khadim_registration() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id=NEW.user_id AND university_id=NEW.university_id) THEN RAISE EXCEPTION 'Volunteer must have a profile in this university'; END IF; IF EXISTS (SELECT 1 FROM public.khadim_schedule WHERE khadim_id=NEW.id AND university_id<>NEW.university_id) THEN RAISE EXCEPTION 'Existing shifts must belong to the volunteer university'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.validate_khadim_registration() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER validate_khadim_registration BEFORE INSERT OR UPDATE ON public.khadim_registrations FOR EACH ROW EXECUTE FUNCTION public.validate_khadim_registration();
CREATE OR REPLACE FUNCTION public.validate_khadim_shift() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.khadim_registrations%ROWTYPE; BEGIN SELECT * INTO r FROM public.khadim_registrations WHERE id=NEW.khadim_id FOR UPDATE; IF r.id IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id=r.user_id AND university_id=NEW.university_id) OR r.university_id<>NEW.university_id THEN RAISE EXCEPTION 'Shift and volunteer must belong to the same university'; END IF; IF NEW.assigned_role NOT IN ('meal_card','food_serving','drinks','cleaning','ittikaf_support') THEN RAISE EXCEPTION 'Choose a valid service role'; END IF; IF EXISTS (SELECT 1 FROM public.khadim_schedule s JOIN public.khadim_registrations other ON other.id=s.khadim_id WHERE other.user_id=r.user_id AND s.assigned_date=NEW.assigned_date AND s.id IS DISTINCT FROM NEW.id AND (s.meal_type=NEW.meal_type OR s.meal_type='both' OR NEW.meal_type='both')) THEN RAISE EXCEPTION 'This student already has a shift for that date and meal'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.validate_khadim_shift() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER validate_khadim_shift BEFORE INSERT OR UPDATE ON public.khadim_schedule FOR EACH ROW EXECUTE FUNCTION public.validate_khadim_shift();
CREATE OR REPLACE FUNCTION public.validate_member_profile_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS (SELECT 1 FROM public.group_members m JOIN public.student_groups g ON g.id=m.group_id WHERE m.user_id=NEW.id AND (g.university_id<>NEW.university_id OR lower(g.gender)<>lower(NEW.gender))) THEN RAISE EXCEPTION 'Existing group membership must match the student university and gender'; END IF; IF EXISTS (SELECT 1 FROM public.khadim_registrations r WHERE r.user_id=NEW.id AND r.university_id<>NEW.university_id) THEN RAISE EXCEPTION 'Existing volunteer registrations must match the student university'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.validate_member_profile_change() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER validate_member_profile_change BEFORE UPDATE OF university_id,gender ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.validate_member_profile_change();
ALTER TABLE public.group_members ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE public.khadim_registrations ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE public.khadim_schedule ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
CREATE TRIGGER group_members_updated_at BEFORE UPDATE ON public.group_members FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER khadim_registrations_updated_at BEFORE UPDATE ON public.khadim_registrations FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER khadim_schedule_updated_at BEFORE UPDATE ON public.khadim_schedule FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uni uuid; BEGIN INSERT INTO public.user_roles(user_id,role) VALUES (NEW.id,'student'); IF NEW.raw_user_meta_data->>'university_id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN uni=(NEW.raw_user_meta_data->>'university_id')::uuid; IF EXISTS (SELECT 1 FROM public.universities WHERE id=uni) AND NEW.raw_user_meta_data->>'gender' IN ('male','female') AND length(trim(COALESCE(NEW.raw_user_meta_data->>'full_name','')))>0 THEN INSERT INTO public.profiles(id,full_name,phone,gender,university_id,is_cafe_student,is_verified) VALUES(NEW.id,trim(NEW.raw_user_meta_data->>'full_name'),NULLIF(NEW.raw_user_meta_data->>'phone',''),NEW.raw_user_meta_data->>'gender',uni,false,false) ON CONFLICT(id) DO NOTHING; END IF; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.handle_new_user() FROM PUBLIC, anon, authenticated;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['student_groups','group_members','khadim_registrations','khadim_schedule'] LOOP IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename=t) THEN EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I',t); END IF; END LOOP; END $$;